import{_ as s,o as t,c as a,a2 as n}from"./chunks/framework.k9nOhppk.js";const u=JSON.parse('{"title":"Running in production","description":"","frontmatter":{"title":"Running in production"},"headers":[],"relativePath":"guide/running.md","filePath":"guide/running.md","lastUpdated":1791864160000}'),i={name:"guide/running.md"};function o(r,e,d,h,c,p){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="running-in-production" tabindex="-1">Running in production <a class="header-anchor" href="#running-in-production" aria-label="Permalink to &quot;Running in production&quot;">​</a></h1><p>A program with jobs is meant to keep running: for the three days a question waits for an answer, for the two hours until access expires, across deploys, crashes and reboots. Usually that takes a database for the state, a queue for the work, a scheduler for the timers, and a config file that says where each of them is. <code>eye run</code> is all of that for one machine: it runs the program, keeps its state in one file, and picks up where it stopped after a restart. Its configuration is the environment.</p><p>This page runs the program from <a href="/tutorial/approvals">All together: approvals</a>, with small local stand-ins for the services it calls. Output shown here is from real runs.</p><h2 id="eye-run" tabindex="-1">eye run <a class="header-anchor" href="#eye-run" aria-label="Permalink to &quot;eye run&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">eye</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--journal </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">file</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> --memory]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [program-directory] [-- arguments…]</span></span></code></pre></div><p><code>eye run</code> does two things, in order:</p><ol><li>It runs <code>main</code>, if the program has one, with the arguments after <code>--</code>. <code>main</code> runs on every start.</li><li>If the program declares jobs, it stays up and runs them: runs started by <code>main</code> or by entity methods, sleeping runs when their time comes, schedules when they fire, and runs that events start or wake.</li></ol><p>It stops when nothing is left that could happen (no schedule, and no run that waits), or when you stop it with Ctrl-C or SIGTERM. A program without jobs stops after <code>main</code>.</p><p>Everything the program keeps (entities, runs, events) goes into its <strong>journal</strong>, <code>.eye/journal</code> in the program&#39;s directory. <code>--journal file</code> puts it somewhere else, such as a volume that outlives the container. <code>--memory</code> keeps everything in memory, so nothing survives the process; use it to try things out.</p><p>Here the approvals program takes a request from the command line:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/tutorial/code/approvals</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NOTIFY_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://127.0.0.1:18473</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ACCESS_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://127.0.0.1:18473</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AI_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://127.0.0.1:18473/v1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  NOTIFY_TOKEN=…</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EYE_EVENTS_PORT=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8080</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eye</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> r-1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ann</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prod-db</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;fix the stuck migration&quot;</span></span></code></pre></div><p><code>main</code> submits the request, which starts the <code>review</code> job. The job asks the model for a summary, sends the approver a question, and then waits up to three days for an answer, which Notify sends to port 8080 (see <a href="#events-between-programs">Events between programs</a>). The program prints nothing more while it waits. Stop it with Ctrl-C; it exits with status 0.</p><h2 id="looking-at-the-journal-eye-runs" tabindex="-1">Looking at the journal: eye runs <a class="header-anchor" href="#looking-at-the-journal-eye-runs" aria-label="Permalink to &quot;Looking at the journal: eye runs&quot;">​</a></h2><p><code>eye runs</code> lists the runs in the journal: what each one waits for, until when, and how much space it takes.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ eye runs .</span></span>
<span class="line"><span>.eye/journal: 7.2 KiB on disk, 1.8 KiB live, 6.7 GiB free; 1 runs, 1 not finished</span></span>
<span class="line"><span>#1 review(&quot;r-1&quot;, { person: &quot;ann&quot;, group: &quot;prod-db&quot;, reason: &quot;fix the stuck migration&quot;, lasting: 2 h })  waiting for the event notify.answered until 2026-10-14 02:23:35 (in 71h59m58s)  [5 steps, 922 B]</span></span></code></pre></div><p>With a run&#39;s number it shows the run&#39;s steps, each with the value that was saved:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ eye runs . 1</span></span>
<span class="line"><span>#1 review(&quot;r-1&quot;, { person: &quot;ann&quot;, group: &quot;prod-db&quot;, reason: &quot;fix the stuck migration&quot;, lasting: 2 h })  waiting for the event notify.answered until 2026-10-14 02:23:35 (in 71h58m54s)  [5 steps, 922 B]</span></span>
<span class="line"><span>    1. step → Ok({ text: &quot;Ann wants two hours on the production database to fix a stuck migration.&quot;, risk: High(r…</span></span>
<span class="line"><span>    2. Request(r-1).summarise</span></span>
<span class="line"><span>    3. notify.ask → Asking(&quot;q-1&quot;)</span></span>
<span class="line"><span>    4. reconcile → Asking(&quot;q-1&quot;)</span></span>
<span class="line"><span>    5. next, waiting until 2026-10-14 02:23:35 (in 71h58m54s)</span></span></code></pre></div><p><code>--json</code> prints the same as JSON, for scripts and dashboards:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ eye runs --json .</span></span>
<span class="line"><span>[</span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>    &quot;id&quot;: 1,</span></span>
<span class="line"><span>    &quot;job&quot;: &quot;review&quot;,</span></span>
<span class="line"><span>    &quot;status&quot;: &quot;sleeping&quot;,</span></span>
<span class="line"><span>    &quot;args&quot;: [</span></span>
<span class="line"><span>      &quot;\\&quot;r-1\\&quot;&quot;,</span></span>
<span class="line"><span>      &quot;{ person: \\&quot;ann\\&quot;, group: \\&quot;prod-db\\&quot;, reason: \\&quot;fix the stuck migration\\&quot;, lasting: 2 h }&quot;</span></span>
<span class="line"><span>    ],</span></span>
<span class="line"><span>    &quot;wakeAt&quot;: &quot;2026-10-14T02:23:35.613142+01:00&quot;,</span></span>
<span class="line"><span>    &quot;waits&quot;: &quot;the event notify.answered&quot;,</span></span>
<span class="line"><span>    &quot;steps&quot;: [</span></span>
<span class="line"><span>      {</span></span>
<span class="line"><span>        &quot;call&quot;: &quot;step&quot;,</span></span>
<span class="line"><span>        &quot;value&quot;: &quot;Ok({ text: \\&quot;Ann wants two hours on the production database to fix a stuck migration.\\&quot;, risk: High(r…&quot;,</span></span>
<span class="line"><span>        &quot;status&quot;: &quot;done&quot;</span></span>
<span class="line"><span>      },</span></span>
<span class="line"><span>      …</span></span>
<span class="line"><span>      {</span></span>
<span class="line"><span>        &quot;call&quot;: &quot;next&quot;,</span></span>
<span class="line"><span>        &quot;until&quot;: &quot;2026-10-14T02:23:35.613142+01:00&quot;,</span></span>
<span class="line"><span>        &quot;status&quot;: &quot;waiting&quot;</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>    ],</span></span>
<span class="line"><span>    &quot;stepCount&quot;: 5,</span></span>
<span class="line"><span>    &quot;size&quot;: 922,</span></span>
<span class="line"><span>    &quot;started&quot;: &quot;2026-10-11T02:23:35.607918+01:00&quot;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>]</span></span></code></pre></div><p><code>eye runs</code> reads the journal without changing it, so it works while <code>eye run</code> is running. It takes <code>--journal</code> too. Only <code>--retry</code> and <code>--retry-failed</code> change anything (see <a href="#retrying-a-failed-run">Retrying a failed run</a>).</p><h2 id="restarts" tabindex="-1">Restarts <a class="header-anchor" href="#restarts" aria-label="Permalink to &quot;Restarts&quot;">​</a></h2><p>Start the program again with the same command. This is what happens:</p><ul><li>The journal is read back: entities, events, and every run as of its last step. Only the records of runs that are ready to run come into memory; a waiting run&#39;s record stays in the file until the run wakes.</li><li><code>main</code> runs again. Here <code>submit</code> sees a request it already has and does nothing, which is why <code>main</code> should be safe to run twice. A job that <code>main</code> starts directly needs a <code>key:</code>, so that starting it again starts nothing; the checker refuses the call without one.</li><li>Waiting runs carry on from their last step. A run whose time came while the program was down runs at once.</li><li>A schedule that missed firings while the program was down fires once, for the latest.</li><li>A command whose reply was lost, and that wasn&#39;t settled yet, is still known, so reconciling it carries on (see <a href="/guide/contracts#when-the-reply-is-lost-uncertain">Talking to other services</a>).</li></ul><p>The stand-ins&#39; log after two starts and two stops shows one model call and one question:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /v1/chat/completions</span></span>
<span class="line"><span>POST /v1/ask key=review-r-1</span></span></code></pre></div><p>The model&#39;s answer and the question&#39;s reply were saved as steps, so the second start used them instead of calling again.</p><p>A step that was in progress when the program stopped didn&#39;t save its result, so it runs again after the restart. That is the reason commands carry keys: running the step again can&#39;t do its work twice. Stopping with <code>kill -9</code>, or losing power, is as safe as Ctrl-C, since each step is on disk before the run goes on.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>A program&#39;s configuration is its environment. Nothing about addresses or credentials is written in the code, and there is no configuration file. (<code>eye.toml</code> marks the program&#39;s root and holds nothing yet.)</p><table tabindex="0"><thead><tr><th>Variable</th><th>What it sets</th><th>Read by</th></tr></thead><tbody><tr><td><code>&lt;MODULE&gt;_URL</code></td><td>The base URL of the service behind a contract module: <code>NOTIFY_URL</code> for <code>notify</code>, <code>SHOP_PAYMENTS_URL</code> for <code>shop.payments</code></td><td>Every call to that contract</td></tr><tr><td><code>&lt;MODULE&gt;_PORT</code></td><td>The port a contract the program serves listens on instead of its <code>@port</code>: <code>NOTIFY_PORT=8081</code>; <code>0</code> takes any free port</td><td><code>eye run</code>, when it starts</td></tr><tr><td><code>EYE_EVENTS_PORT</code></td><td>The port the program takes other services&#39; events on, besides the ports of the contracts it serves; <code>0</code> takes any free port</td><td><code>eye run</code>, when it starts</td></tr><tr><td><code>&lt;MODULE&gt;_EVENTS_URL</code></td><td>Where the events of a contract the program serves go: the base URLs of the programs that take them, separated by commas or spaces, such as <code>NOTIFY_EVENTS_URL=http://approving:8080,http://trains:8080</code></td><td>Each event published</td></tr><tr><td><code>AI_URL</code></td><td>The model gateway&#39;s base URL, such as <code>http://gateway:8317/v1</code>; when set, it answers every model</td><td><code>ai.generate</code></td></tr><tr><td><code>ANTHROPIC_URL</code>, <code>OPENAI_URL</code></td><td>Where Anthropic&#39;s and OpenAI&#39;s APIs are, if not at their usual addresses</td><td><code>ai.generate</code></td></tr><tr><td><code>AI_PRICES</code></td><td>Prices of models for <code>@budget(usd:)</code>, in dollars per million tokens in and out: <code>gpt-5.5=1.25/10,…</code></td><td><code>@budget</code></td></tr><tr><td>A secret&#39;s name in upper case, with <code>-</code> and <code>.</code> as <code>_</code></td><td>A secret: <code>PAYMENTS_TOKEN</code> for <code>secret(&quot;payments-token&quot;)</code></td><td><code>secret(…)</code>, <code>@auth</code>, and the providers&#39; keys <code>ai-key</code>, <code>anthropic-api-key</code> and <code>openai-api-key</code></td></tr><tr><td><code>EYE_SECRETS</code></td><td>A directory with one file per secret, named after it, read when the variable isn&#39;t set</td><td><code>secret(…)</code></td></tr><tr><td>Any name you choose</td><td>Configuration that isn&#39;t secret, such as a proxy&#39;s address</td><td><code>env.get(&quot;VPN_PROXY_URL&quot;)</code></td></tr></tbody></table><p>Secrets come from the environment variable first, then from <code>$EYE_SECRETS/&lt;name&gt;</code>, without the file&#39;s trailing newline. Kubernetes and systemd mount secrets as files, so point <code>EYE_SECRETS</code> at that directory and keep secrets out of the environment. A <code>Secret(String)</code> can&#39;t be shown, logged or saved, so it can&#39;t leak into the journal or a log line.</p><p><code>env.get(name)</code> returns an <code>Option(String)</code> and has the effect <code>env</code>, so a public function that reads configuration says so in its signature. In a job, or a function with <code>!</code> steps, the read is a recorded step, <code>env.get!(…)</code>: a resumed run sees the value it read before, even if the variable has changed since. See <a href="/guide/effects">Effects</a>.</p><p>Settings are read when they are used, not when the program starts. A missing one stops the run that needed it, with a message that names the variable. From the <a href="/guide/contracts">contracts guide&#39;s program</a>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main.eye:42:16: job collect: payments.charge calls another service: set PAYMENTS_URL to its address, or replay recordings with \`with fakes(payments, from: &quot;…&quot;)\`</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main.eye:42:16: job collect: secret &quot;payments-token&quot; isn&#39;t set: set PAYMENTS_TOKEN, or put a file payments-token in $EYE_SECRETS</span></span></code></pre></div><p>and from the <a href="/guide/ai-calls">AI calls guide&#39;s program</a>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main.eye:59:3: job triage: ai.generate asks Anthropic for claude-sonnet-5-5, and has no key: set ANTHROPIC_API_KEY, or put it in $EYE_SECRETS/anthropic-api-key</span></span></code></pre></div><p>A program that serves a contract itself (with <code>impl</code>) calls its own implementation, unless that contract&#39;s <code>&lt;MODULE&gt;_URL</code> is set.</p><h2 id="serving-a-contract" tabindex="-1">Serving a contract <a class="header-anchor" href="#serving-a-contract" aria-label="Permalink to &quot;Serving a contract&quot;">​</a></h2><p>A program that serves a contract with <code>impl</code> answers other programs too: <code>eye run</code> listens on the contract&#39;s <code>@port</code>, on every network interface, and keeps running until it is stopped, even when no job is left to wait for. It says where when it starts:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>eye run: serving notify.Notify on :3001</span></span></code></pre></div><p>Requests are routed by the contract&#39;s <code>@http</code> attributes, read and answered in the contract&#39;s JSON shape, and each runs its operation as one transaction. An operation without <code>@http</code> is reached only from inside the program. With <code>@auth</code>, <code>eye run</code> reads the secret when it starts, and won&#39;t start without it; a request without it gets 401. See <a href="/guide/contracts#implementing-the-other-side">Talking to other services</a>.</p><p><code>NOTIFY_PORT</code> (the module&#39;s name, as for <code>NOTIFY_URL</code>) moves the service to another port, and <code>NOTIFY_PORT=0</code> to any free one, which the line above names. Tests use it to run a server and its callers side by side.</p><h2 id="events-between-programs" tabindex="-1">Events between programs <a class="header-anchor" href="#events-between-programs" aria-label="Permalink to &quot;Events between programs&quot;">​</a></h2><p>A contract&#39;s events go from the program that serves the contract to the programs that wait for them, as HTTP requests. Notify&#39;s <code>answered</code> (<code>event answered: Answered on &quot;notify.answers&quot;</code>) reaches a program as <code>POST /events/notify.answers</code>, with the event as JSON in the contract&#39;s shape and the contract&#39;s <code>@auth</code> secret, the same one its callers send.</p><p><strong>Taking events.</strong> A program takes each event it consumes, with <code>@on(event(…))</code> or <code>next!</code>, of a contract it doesn&#39;t serve. It takes them on the ports of the contracts it serves, and on <code>EYE_EVENTS_PORT</code>, which a program that serves nothing needs:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>eye run: taking notify.answered on :8080</span></span></code></pre></div><ul><li>An event is answered 202 once it is in the journal. It then starts its <code>@on</code> jobs and wakes the runs waiting for it in <code>next!</code>, as an event the program published itself would.</li><li>An event with <code>@key</code> that comes again is answered 202 and starts nothing, so a sender may always send again when it isn&#39;t sure.</li><li>A request without the contract&#39;s secret gets 401; a body that isn&#39;t the event&#39;s type, 400.</li><li>Only events of contracts with <code>@auth</code> are taken: without one, anyone who reaches the port could publish them. <code>eye run</code> names such events when it starts (<code>telegram.updates has no way in: contract Telegram has no @auth, so anyone could publish it</code>), and also those it has no port for.</li></ul><p><strong>Sending events.</strong> A program that serves a contract sends the contract&#39;s events to each URL in <code>&lt;MODULE&gt;_EVENTS_URL</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NOTIFY_EVENTS_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://approving:8080,http://trains:8080</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> eye</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><ul><li>Each event, and a delivery for each subscriber, is saved in the journal with the commit that publishes it, then sent. Nothing published is lost by a crash: after a restart, what wasn&#39;t delivered is sent.</li><li>A subscriber that doesn&#39;t answer, or answers with a 5xx, gets the event again after half a second, then a second, doubling to every 30 seconds, until it takes it. Each subscriber gets events in the order they were published.</li><li>A 4xx answer, such as 401 for a wrong secret or 404 for a wrong URL, is a mistake in the configuration: the delivery is dropped, with a line that names the subscriber and its answer. So is one not taken within 30 days.</li><li>So an event arrives at least once, and one with <code>@key</code> starts its jobs once.</li></ul><p>A service written in Go or TypeScript sends events with the sender <code>eye gen go</code> or <code>eye gen ts</code> writes for each one, such as <code>SendAnswered</code>, and keeps them until they are taken.</p><h2 id="when-a-run-fails" tabindex="-1">When a run fails <a class="header-anchor" href="#when-a-run-fails" aria-label="Permalink to &quot;When a run fails&quot;">​</a></h2><p>A run that stops on a bug, such as a request the service refuses, a missing setting, or an <code>unreachable</code>, is printed on standard error, and <code>eye run</code> exits with status 1 when it stops:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main.eye:51:16: job collect: payments.charge was refused with status 404: {&quot;error&quot;: &quot;no such route&quot;}</span></span></code></pre></div><p>The run stays failed in the journal, with its message:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#1 collect(&quot;i-3&quot;, &quot;cara&quot;, 1500, &quot;+353 85 000 0003&quot;)  failed: main.eye:51:16: payments.charge was refused with status 404: {&quot;error&quot;: &quot;no such route&quot;}  [0 steps, 391 B]</span></span></code></pre></div><p>Fixing the setting and starting again doesn&#39;t start that run again: <code>main</code> runs, the invoice already exists, and nothing new happens. So check the configuration before the first start, for example by running once with <code>--memory</code> against the real services.</p><h3 id="retrying-a-failed-run" tabindex="-1">Retrying a failed run <a class="header-anchor" href="#retrying-a-failed-run" aria-label="Permalink to &quot;Retrying a failed run&quot;">​</a></h3><p>A run that failed because something outside the program wasn&#39;t there can be started again once it is: a service that stayed out of reach for longer than its retries (<code>Unavailable</code>), or a run that ran out of time (<code>DeadlinePassed</code>). <code>eye runs --retry</code> takes the run&#39;s id:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ eye runs --retry 1 .</span></span>
<span class="line"><span>run 1 (collect) is ready again: eye run . carries it on, replaying its 2 recorded steps</span></span></code></pre></div><p>The run keeps its id and key, so <code>main</code>&#39;s keyed start and a parent&#39;s <code>join!</code> find it, and it replays the steps it recorded before the fault: a charge that went through isn&#39;t sent again. Its <code>@deadline</code> counts from when it runs again. <code>eye runs --retry-failed</code> retries every failed run that ended so. While <code>eye run</code> holds the journal, the retry goes to its inbox, and the runner starts the run within a second:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ eye runs --retry 1 .</span></span>
<span class="line"><span>retrying run 1 (collect): eye run, which holds the store, starts it within a second, replaying its 2 recorded steps</span></span></code></pre></div><p>Any other failure is refused, with the reason. A refused request like the one above, <code>unreachable</code> and other bugs end as <code>Unreachable</code> and would fail the same way again; <code>Killed</code> was on purpose. A run that failed inside <code>lock!</code> or <code>reserve!</code> can&#39;t be retried either, since it gave the lock or the memory back as it ended.</p><h2 id="the-journal" tabindex="-1">The journal <a class="header-anchor" href="#the-journal" aria-label="Permalink to &quot;The journal&quot;">​</a></h2><p>The journal is one file that only <code>eye run</code> writes:</p><ul><li><p><strong>Each change is on disk before anyone can see it.</strong> Each commit, such as a step with the entity changes it made, is one line, appended at once. The journal is synced before <code>eye run</code> does anything outside: before it calls a service, runs a program, writes a file, prints, answers a request, or waits. One sync covers every commit made since the last, so <code>main</code> starting 5,000 runs takes a third of a second, not four. A last line cut short by a crash is dropped when the journal is read, and so are zeros a crash left where commits never reached the disk, with what follows: nothing outside had seen those changes.</p></li><li><p><strong>Each line is small.</strong> A run&#39;s record is written as JSON, and a run whose last 20 steps (what <code>eye runs</code> shows) moved on is written with only the steps they gained. A journal written by an <code>eye</code> before 2026-10-12 opens as before and is written in this form from then on.</p></li><li><p><strong>A waiting run costs about 140 bytes of memory.</strong> The record of a run that waits or has finished stays in the file, written whole when the run starts to wait, and <code>eye run</code> keeps only what finds it: when it wakes and what wakes it. The record is read back when the run wakes, or when something asks for it. 20,000 runs sleeping for a day add about 7 MB to <code>eye run</code>.</p></li><li><p><strong>It grows with the state, not the history.</strong> When <code>eye run</code> opens the journal, and whenever it grows past four times the live data (and past 1 MiB), it is rewritten as a snapshot, through a new file renamed over the old one. Above, 7.2 KiB on disk with 1.8 KiB live became 1.8 KiB after the restart.</p></li><li><p><strong>Old detail is dropped.</strong> Once an hour, <code>eye run</code> drops what no run can use any more: events every waiting run has seen, event keys older than 30 days, and the steps of runs that finished more than 7 days ago, which keep a summary. Waiting runs and unsettled commands are never dropped.</p></li><li><p><strong>A full disk changes nothing.</strong> A change that can&#39;t be written is undone, and tried again 10 seconds later. Beside the journal, <code>journal.reserve</code> holds 4 MiB that is given back when a write fails, so the rewrite that frees space can still finish.</p></li><li><p><strong>One writer.</strong> <code>journal.lock</code> makes sure that only one <code>eye run</code> uses a journal. A second one stops at once:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>eye run: .eye/journal is in use by another eye run</span></span></code></pre></div><p>So run one instance of a program per journal. To keep the state off the machine, use the Postgres store instead, <code>eye run --store postgres://…</code>, which also takes one runner per database and schema.</p></li></ul><p>A job that never ends, such as a <code>while true</code> loop that sleeps, stays small: a run keeps a checkpoint between the statements of its job, and each wake replays only the steps taken since the last one. Steps inside a function the job calls have no checkpoint between them, so <code>eye run</code> warns once when a run passes 1,000 steps since its last checkpoint.</p><p><strong>Backups.</strong> Copy the <code>journal</code> file; the <code>.lock</code> and <code>.reserve</code> files beside it aren&#39;t needed. A copy taken while <code>eye run</code> is running is still usable, because every change is a whole line and a cut-short last line is dropped when the journal is read. To restore, stop the program, put the copy at <code>.eye/journal</code> (or wherever <code>--journal</code> points), and start it again.</p><h2 id="stopping" tabindex="-1">Stopping <a class="header-anchor" href="#stopping" aria-label="Permalink to &quot;Stopping&quot;">​</a></h2><p>Ctrl-C (SIGINT) and SIGTERM stop <code>eye run</code>, and it exits with status 0 unless a run failed. Nothing is lost: every step that finished is already in the journal, and a step that was cut off runs again on the next start. A service manager can stop and restart the program at any time.</p><p>A signal also stops <code>main</code> while it waits, for a timer, a service, its tasks or a channel: it prints <code>eye run: stopped while main ran</code> and exits. <code>main</code> is ordinary code, so stopping it half-way loses nothing the journal keeps. Code that computes without ever waiting isn&#39;t interrupted; a second Ctrl-C ends the process.</p><p>A minimal systemd unit, with secrets mounted as credentials:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Unit]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=Access approvals</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Service]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WorkingDirectory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/srv/approvals</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ExecStart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/usr/local/bin/eye run .</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOTIFY_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=http://notify:3001 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ACCESS_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=http://access:8080 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AI_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=http://gateway:8317/v1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LoadCredential</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=ai-key:/etc/approvals/ai-key</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">EYE_SECRETS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=%d</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Restart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=on-failure</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Install]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WantedBy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=multi-user.target</span></span></code></pre></div><h2 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to &quot;Checklist&quot;">​</a></h2><ul><li>Every service the program calls has its <code>&lt;MODULE&gt;_URL</code>, and every secret is set or in <code>$EYE_SECRETS</code>.</li><li>Every contract the program serves has its port free, and its callers can reach it.</li><li>Every event the program waits for from another service is taken (<code>eye run: taking …</code>), and the service that sends it lists the program in its <code>&lt;MODULE&gt;_EVENTS_URL</code>.</li><li><code>main</code> is safe to run on every start, and jobs it starts have keys.</li><li>Commands that change something have <code>@key</code>, so a step that runs again does nothing twice.</li><li>The journal is on a disk that survives a redeploy, and it is backed up.</li><li>One <code>eye run</code> per journal.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/reference/cli#run">The eye command</a>: every flag of <code>eye run</code> and <code>eye runs</code>.</li><li><a href="/reference/language/programs-and-concurrency">Programs and concurrency</a>: <code>main</code>, modules and <code>eye run</code>.</li><li><a href="/reference/language/time-secrets-tests">Time, secrets, tests</a>: secrets and <code>env.get</code>.</li><li><a href="/guide/jobs-and-waiting">Jobs and waiting</a>: what a step saves.</li><li><a href="/guide/contracts">Talking to other services</a> and <a href="/guide/ai-calls">AI calls</a>: the services the settings point at.</li></ul>`,78)])])}const g=s(i,[["render",o]]);export{u as __pageData,g as default};
